/** Posts one of LibraryDB's mutations outside any Engine, as the session or as anonymous,
    numbered in a series of its own so the transport may retry it. */
public func postLibraryMutation(
    _ transport: any Transport,
    _ mutation: some LibraryDBMutation,
    session: Session? = nil
) async throws -> MutationResult {
    let data = try registry.encode("LibraryDBMutation", mutation)
    let m = Mutation(id: generateUuid(), series: generateSeries(), n: 1, data: data)
    return try await transport.post([m], session: session)[0]
}

